"
        declare function local:test($test as xs:integer) as xs:integer? { 
          if ($test = 1) then ( 0 ) else if ($test = 2) then ( 9 ) else if ($test = 3) then ( 13 ) else if ($test = 4) then ( 16 ) else () 
        }; 
        fn:codepoints-to-string( local:test(2) to 32 )"

"
      declare function local:test($test as xs:integer) as xs:integer? { 
        if ($test = 1) then ( 0 ) else if ($test = 2) then ( 9 ) else if ($test = 3) then ( 13 )else if ($test = 4) then ( 16 ) else () 
      }; 
      fn:codepoints-to-string( local:test(3) to 32 )"

"declare function local:test($test as xs:integer) as xs:integer? { 
        if ($test = 1) then ( 0 ) else if ($test = 2) then ( 9 ) else if ($test = 3) then ( 13 ) else if ($test = 4) then ( 16 ) else () 
      }; 
      fn:codepoints-to-string( local:test(4) to 32 )"

"
         declare variable $d1 := <e a="1" b="2">te<?target data?>xt</e>; 
         declare variable $d2 := <e b="2" a="1">text</e>; 
         deep-equal($d1, $d2), deep-equal($d2, $d1)
      "

"
         declare variable $d1 := <e a="1" b="2">te<!-- content -->xt</e>; 
         declare variable $d2 := <e b="2" a="1">text</e>; 
         deep-equal($d1, $d2), deep-equal($d2, $d1)
      "

"
        xquery version "3.0";
      	declare %private function local:square($i as xs:integer) as xs:integer { $i*$i };
        function-lookup(QName("http://www.w3.org/2005/xquery-local-functions", "square"), 1)(13, 12)
      "

"
      let $module-ns := "http://www.w3.org/fots/fn/load-xquery-module/import/module",
       $module := fn:load-xquery-module($module-ns),
       $mod1-ns := "http://www.w3.org/TestModules/module1"
      return
      let $fns := $module("functions")
      let $f0 := $fns(QName($mod1-ns, "x"))(0)
      return $f0(0)()
    "

"
      	declare function local:f($x as xs:integer) {
      		 if ($x = 3) then xs:duration("P1D") else xs:dayTimeDuration("PT3S") 
      	}; 
      	max(for $x in (1,2,3) return local:f($x))
      "

"
      	declare function local:f($x as xs:integer) {
      		 (xs:decimal(1.1), xs:float(2.2), xs:double(1.4), xs:integer(2))[$x] 
      	}; 
      	max(for $x in (1,2,3) return local:f($x)) instance of xs:double
      "

"
      	declare function local:f($x as xs:integer) { 
      		(xs:decimal(1.1), xs:float(1.2), xs:double(0.4), xs:integer("-3"))[$x] 
      	}; 
      	max(for $x in (4,2,1,3) return local:f($x)) instance of xs:double
      "

"
      	declare function local:f($x as xs:integer) { 
      		if ($x = 3) then xs:duration("P1Y") else xs:yearMonthDuration("P11M") 
      	}; 
      	max(for $x in (1,2,3) return local:f($x))
      "

"
      	declare function local:f($x as xs:integer) as xs:duration { 
      		if ($x = 1) then xs:duration("P1Y") else xs:yearMonthDuration("P11M") 
      	}; 
      	max(for $x in (1,2,3) return local:f($x))"

"
        declare namespace err="http://www.w3.org/2005/xqt-errors";
      	<results>{
      		for $t in /tests/test
      		return try {
      		    let $matches := matches($t/@input, $t/@regex, string($t/@flags))
      		    return
      		       if ($matches (:trace($matches, $t/@id):) and $t/@result ne 'y')
      		         then <fail>{$t}</fail>
      		       else if (not($matches) and $t/@result ne 'n') 
      		         then <fail>{$t}</fail>
      		       else ()
      	    } catch * {
      	        if ($t/@result = ('y', 'n'))
      	        then <fail error="{$err:code}">{$t}</fail>
      	        else ()
      	    }   
      	}</results>
      "

